async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  limit: number | undefined,
  before: {sessionId: string; updatedAt: string} | undefined
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit, before});
    const sessions = summaries.map(s => ({
      ...s,
      createdAt: s.createdAt.toISOString(),
      updatedAt: s.updatedAt.toISOString(),
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    log.error('ws', 'failed to list sessions', {
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

